import contextlib
import csv
import sys


class CSVUtils:
    """Read CSV data lazily, loading the whole file exactly once.

    The special filepath "-" reads from standard input.  ``_load`` consumes the
    stream only once and caches both column names and data rows, so a second
    call never re-reads stdin.
    """

    def __init__(self, csv_filepath):
        self.filepath = csv_filepath
        self._column_names = None
        self._data_rows = None
        self._loaded = False

    @contextlib.contextmanager
    def open_csv(self, mode="r", newline=""):
        if self.filepath == "-":
            yield sys.stdin
            return
        with open(
            self.filepath, mode, newline=newline, encoding="utf-8-sig"
        ) as csv_file:
            yield csv_file

    def _load(self):
        if self._loaded:
            return
        with self.open_csv("r", newline="") as csv_file:
            rows = list(csv.reader(csv_file))
        self._column_names = rows[0] if rows else []
        self._data_rows = [row for row in rows[1:] if row != []]
        self._loaded = True

    def get_column_names(self):
        self._load()
        return list(self._column_names)

    def get_data_rows(self):
        self._load()
        return [list(row) for row in self._data_rows]
