import argparse
import ast
import json
import sys

from .hone import Hone
from .utils import output_json


def _build_parser():
    parser = argparse.ArgumentParser(
        prog="hone",
        description="Convert CSV to automatically nested JSON.",
    )
    parser.add_argument(
        "csv_filepath",
        help=(
            "Specify the filepath for the file to read CSV data from. "
            'To read from standard input, use a dash ("-") as the value'
        ),
    )
    parser.add_argument(
        "json_filepath",
        help=(
            "Specify the filepath for the file to output JSON data to. "
            'To write to standard output, use a dash ("-") as the value.'
        ),
    )
    parser.add_argument(
        "-d",
        "--delimiters",
        nargs="?",
        const=None,
        default=None,
        help=(
            "Override the default delimiters for generating a nested structure "
            "from column names. [DELIMITERS] must be a Python-compatible list of "
            "strings. The default value is [',', '_', ' ']."
        ),
    )
    parser.add_argument(
        "-s",
        "--schema",
        nargs="?",
        const=None,
        default=None,
        help=(
            "Manually specify the schema that defines the structure of the "
            "generated JSON, instead of having it automatically generated. "
            "[SCHEMA] must be a valid JSON object encoded as a string."
        ),
    )
    return parser


def _parse_delimiters(parser, raw):
    if raw is None:
        return list(Hone.DEFAULT_DELIMITERS)
    value = None
    try:
        value = ast.literal_eval(raw)
    except (ValueError, SyntaxError):
        try:
            value = json.loads(raw)
        except (ValueError, TypeError):
            parser.error(
                "--delimiters must be a Python-compatible list of strings"
            )
    if (
        not isinstance(value, list)
        or not value
        or not all(isinstance(item, str) for item in value)
    ):
        parser.error("--delimiters must be a non-empty list of strings")
    return value


def _parse_schema(parser, raw):
    if raw is None:
        return None
    try:
        value = json.loads(raw)
    except (ValueError, TypeError):
        parser.error("--schema must be a valid JSON object encoded as a string")
    if not isinstance(value, dict):
        parser.error("--schema must be a JSON object")
    return value


def main(argv=None):
    parser = _build_parser()
    args = parser.parse_args(argv)
    delimiters = _parse_delimiters(parser, args.delimiters)
    schema = _parse_schema(parser, args.schema)

    try:
        hone = Hone(delimiters=delimiters)
        json_struct = hone.convert(args.csv_filepath, schema=schema)
        output_json(json_struct, args.json_filepath)
    except Exception as exc:  # noqa: BLE001 - CLI boundary
        sys.stderr.write("hone: error: {}\n".format(exc))
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
